"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1354],{29970:e=>{e.exports=JSON.parse('{"functions":[{"name":"start","desc":"Installs [MarketplaceService._processReceipt] as the game\'s\\n`MarketplaceService.ProcessReceipt` handler and starts dropping a player\'s\\nstaged pending purchases when they leave.","params":[],"returns":[],"function_type":"static","source":{"line":78,"path":"src/Server/Features/Shop/MarketplaceService.luau"}},{"name":"thank","desc":"Sends the \\"Thank you for your purchase!\\" toast. Currently not called from\\nthe receipt flow \u2014 the call site in [MarketplaceService._processReceipt] is\\ncommented out.","params":[{"name":"player","desc":"buyer to thank","lua_type":"Player"}],"returns":[],"function_type":"static","source":{"line":106,"path":"src/Server/Features/Shop/MarketplaceService.luau"}},{"name":"setPendingPurchase","desc":"Stages context for an upcoming purchase, keyed by product and player.\\n\\nCall this **before** prompting the purchase. The receipt processor hands the\\nstored value to every matching [MarketplaceData] callback, which is how a\\ngeneric product learns which item it should grant.","params":[{"name":"productId","desc":"developer product id","lua_type":"number"},{"name":"player","desc":"prospective buyer","lua_type":"Player"},{"name":"data","desc":"context for the fulfilment callback, typically an itemId","lua_type":"any"}],"returns":[],"function_type":"static","source":{"line":129,"path":"src/Server/Features/Shop/MarketplaceService.luau"}},{"name":"getPendingPurchaseData","desc":"Reads back the context staged for a product/player pair, or nil when none\\nwas staged.","params":[{"name":"productId","desc":"developer product id","lua_type":"number"},{"name":"player","desc":"buyer","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"any?"}],"function_type":"static","source":{"line":147,"path":"src/Server/Features/Shop/MarketplaceService.luau"}},{"name":"clearPendingPurchase","desc":"Drops the staged context for a product/player pair, collapsing the product\'s\\nentry once no players remain under it. Called after a receipt is\\nsuccessfully fulfilled.","params":[{"name":"productId","desc":"developer product id","lua_type":"number"},{"name":"player","desc":"buyer","lua_type":"Player"}],"returns":[],"function_type":"static","source":{"line":163,"path":"src/Server/Features/Shop/MarketplaceService.luau"}},{"name":"checkOwnershipLimit","desc":"Checks whether a Robux purchase would push the player past an item\'s\\nownership limit.\\n\\nThe item being bought is read from the staged pending-purchase data, so a\\nproduct with nothing staged is treated as unlimited and passes. Counts\\ninventory quantity, plus placed props for `Prop` items \u2014 that second term\\ncurrently always reads zero, since `BaseService` here is a local stub\\npending the Base system port.","params":[{"name":"player","desc":"buyer","lua_type":"Player"},{"name":"productId","desc":"developer product id","lua_type":"number"}],"returns":[{"desc":"whether the purchase is permitted","lua_type":"boolean"},{"desc":"how many the player already owns","lua_type":"number"},{"desc":"the item\'s ownership limit","lua_type":"number"}],"function_type":"static","source":{"line":193,"path":"src/Server/Features/Shop/MarketplaceService.luau"}},{"name":"_processReceipt","desc":"The developer product purchase flow, installed as\\n`MarketplaceService.ProcessReceipt`.\\n\\n1. Don\'t allow processing for the same receipt if it is currently in the\\n   purchase flow.\\n2. Confirm player is in the server.\\n3. Check for duplicates.\\n4. If the product previously failed to save in the user\'s profile, attempt\\n   to save again.\\n5. Confirm the product is a valid product created by us.\\n6. Give user the product.\\n7. Save the user\'s profile (if required); if saving fails return to step 4.\\n\\nStep 6 runs every [MarketplaceData] callback whose filter matches the\\nproduct; if any returns falsy the receipt is abandoned as `NotProcessedYet`\\nand Roblox retries later. Products flagged `dontSave` skip the profile save\\nand are granted immediately.\\n\\nEvery failure path returns `NotProcessedYet` rather than\\n`PurchaseNotProcessedYet`-and-forget, so no purchase is ever silently\\nconsumed \u2014 the tradeoff is that a permanently failing callback will have\\nRoblox retry indefinitely.","params":[{"name":"receiptInfo","desc":"the receipt from Roblox","lua_type":"Types.ReceiptInfo"}],"returns":[{"desc":"","lua_type":"Enum.ProductPurchaseDecision"}],"function_type":"static","private":true,"source":{"line":263,"path":"src/Server/Features/Shop/MarketplaceService.luau"}}],"properties":[],"types":[],"name":"MarketplaceService","desc":"Handles marketplace processing for the shop system \u2014 it owns\\n`MarketplaceService.ProcessReceipt`, so every developer-product purchase in\\nthe game lands here.\\n\\nNote the module table is named `Marketplace` locally so it does not shadow\\nthe Roblox service of the same name.\\n\\n## Idempotence\\n\\nRoblox retries a receipt until it is granted, so the flow is built to be\\nsafe to re-enter. Three pieces of state cooperate:\\n\\n- `inProgress` \u2014 in-memory, keyed by PurchaseId, rejects a concurrent\\n  re-entry for a receipt already being handled.\\n- `profile.purchases[purchaseId]` \u2014 the durable record that a receipt was\\n  granted **and saved**. Its presence short-circuits straight to\\n  `PurchaseGranted`.\\n- `profile.unsaved[purchaseId]` \u2014 a receipt that was granted but whose\\n  profile save failed. The next retry re-attempts only the save, without\\n  re-running the grant, so the player is never given the product twice.\\n\\nBoth records store a timestamp rather than a boolean so they can be expired\\nlater.\\n\\n## Pending purchases\\n\\nSome products need context that the receipt does not carry \u2014 chiefly which\\nitem a generic \\"buy item\\" product should grant. Callers stage that with\\n[MarketplaceService.setPendingPurchase] before prompting, and the receipt\\nprocessor passes it to the callbacks and clears it on success. Pending data\\nis dropped when a player leaves.\\n\\nFulfilment itself lives in the callbacks registered on [MarketplaceData];\\nif any matching callback fails, the receipt returns `NotProcessedYet` and\\nRoblox retries.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Server"],"source":{"line":44,"path":"src/Server/Features/Shop/MarketplaceService.luau"}}')}}]);